import {cabinet,circle,text,line,rect} from './cabinet.js';
import {shuffled,swipeDirection} from './shared.js';
const dirs=[[0,-1,0,2],[1,0,1,3],[0,1,2,0],[-1,0,3,1]];
export function makeMaze(random=Math.random){const cells=Array.from({length:63},()=>[true,true,true,true]),seen=new Set([0]),stack=[0];while(stack.length){const i=stack.at(-1),x=i%7,y=Math.floor(i/7),options=dirs.filter(([dx,dy])=>x+dx>=0&&x+dx<7&&y+dy>=0&&y+dy<9&&!seen.has((y+dy)*7+x+dx));if(!options.length){stack.pop();continue;}const [dx,dy,wall,opposite]=options[Math.floor(random()*options.length)],next=(y+dy)*7+x+dx;cells[i][wall]=false;cells[next][opposite]=false;seen.add(next);stack.push(next);}return cells;}
export function mazeNext(cells,i,d){const wall={up:0,right:1,down:2,left:3}[d];return wall===undefined||cells[i][wall]?i:i+[-7,1,7,-1][wall];}
export function createMaze(mount,api){const q=cabinet(mount,api,{accent:'#aee57e'}),c=q.c;let cells=makeMaze(),player=0,level=1,visited=new Set([0]),gems=new Set(),left=55,delay=0,origin=null,dragged=false;
 function setup(){cells=makeMaze();player=0;visited=new Set([0]);gems=new Set(shuffled(Array.from({length:61},(_,i)=>i+1)).slice(0,3));left=55;delay=0;}
 function move(d){if(!q.active||delay)return;const next=mazeNext(cells,player,d);if(next===player){q.sound('blocked');return;}player=next;visited.add(player);q.sound('step');if(gems.delete(player)){q.add(25);q.sound('gem');q.burst(57+player%7*41,65+Math.floor(player/7)*41);}if(player===62){if(gems.size){q.say(`${gems.size} SPARK${gems.size>1?'S':''} STILL TO FIND`);}else{q.add(100+Math.ceil(left)*3);q.sound('clear');if(level===3)q.finish('Found your way.',`Three mazes. Nine sparks. ${q.score} points.`,true);else{q.say('ESCAPED! A new maze awaits.');delay=.9;}}}}
 function trace(p){const xx=Math.floor((p.x-36)/41),yy=Math.floor((p.y-44)/41),px=player%7,py=Math.floor(player/7);if(xx>=0&&xx<7&&yy>=0&&yy<9&&Math.abs(xx-px)+Math.abs(yy-py)===1){move(xx<px?'left':xx>px?'right':yy<py?'up':'down');dragged=true;}}
 setup();return {start(){level=1;setup();q.start();origin=null;},direction:move,action(){q.say('Collect 3 sparks, then reach the exit');},tap(p){p=q.local(p);const px=56.5+player%7*41,py=64.5+Math.floor(player/7)*41,dx=p.x-px,dy=p.y-py;if(Math.max(Math.abs(dx),Math.abs(dy))>15)move(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up');},pointerDown(p){origin=q.local(p);dragged=false;},pointerMove(p){if(origin)trace(q.local(p));},pointerUp(p){if(origin&&!dragged){const d=swipeDirection(origin,q.local(p));if(d)move(d);}origin=null;},cancel(){origin=null;},tick(dt){q.frame(dt,dt=>{if(delay){delay-=dt;if(delay<=0){level++;setup();}return;}left-=dt;if(left<=0)q.finish('A scenic detour.',`${q.score} points. Your trail marks where you’ve been.`);},()=>{q.header(`MAZE ${level}/3 · ${3-gems.size}/3 SPARKS`,`${Math.max(0,Math.ceil(left))}s`);rect(c,32,40,295,377,'#162e31',8);for(let i=0;i<63;i++){const x=36+i%7*41,y=44+Math.floor(i/7)*41;if(visited.has(i))circle(c,x+20.5,y+20.5,2,'#86b6a966');if(i===62){rect(c,x+6,y+6,29,29,gems.size?'#415c58':'#9adb9a',6);text(c,'↗',x+20.5,y+20.5,20,gems.size?'#91b6a0':'#173936',700);}if(gems.has(i)){text(c,'✦',x+20.5,y+20.5,22,'#ffe394',700);}const wall=cells[i];if(wall[0])line(c,x,y,x+41,y,'#668b7c',2);if(wall[3])line(c,x,y,x,y+41,'#668b7c',2);if(i%7===6&&wall[1])line(c,x+41,y,x+41,y+41,'#668b7c',2);if(i>=56&&wall[2])line(c,x,y+41,x+41,y+41,'#668b7c',2);}circle(c,56.5+player%7*41,64.5+Math.floor(player/7)*41,12,'#aee57e');circle(c,53+player%7*41,61+Math.floor(player/7)*41,3,'#fff9df');q.footer('Trace the paths. Collect ✦. Reach ↗.');});},destroy:q.destroy};}
